CREATE DATABASE IF NOT EXISTS aanshu CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE aanshu;
CREATE TABLE admins (id INT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE content (name VARCHAR(80) PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE projects (id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, image VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reviews (id INT PRIMARY KEY AUTO_INCREMENT, customer VARCHAR(100) NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE enquiries (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(30) NOT NULL, service VARCHAR(100) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE posts (id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(160) NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
